import math, cmath
def chars(q):
    if q == 1:
        return [({0: 1}, True)]
    U = [a for a in range(1, q) if math.gcd(a, q) == 1]
    ph = len(U)
    def closure(gs):
        H = {1}; fr = [1]
        while fr:
            x = fr.pop()
            for g in gs:
                y = x * g % q
                if y not in H: H.add(y); fr.append(y)
        return H
    gens = []; H = {1}
    for a in U:
        if a not in H:
            gens.append(a); H = closure(gens)
    out = []
    import itertools
    for es in itertools.product(range(ph), repeat=len(gens)):
        val = {1: 0}; fr = [1]; ok = True
        while fr and ok:
            x = fr.pop()
            for g, e in zip(gens, es):
                y = x * g % q; v = (val[x] + e) % ph
                if y in val:
                    if val[y] != v: ok = False; break
                else:
                    val[y] = v; fr.append(y)
        if ok and len(val) == ph:
            chi = {u: cmath.exp(2j * cmath.pi * val[u] / ph) for u in U}
            prim = True
            for d in range(1, q):
                if q % d == 0 and all(abs(chi[u] - 1) < 1e-9 for u in U if u % d == 1 % d):
                    prim = False; break
            out.append((chi, prim))
    return out
def ev(chi, q, n):
    if q == 1: return 1
    r = n % q
    return chi.get(r, 0) if math.gcd(r, q) == 1 else 0

import random
random.seed(7)
Q, M, N = 10, 17, 40
cs = {n: complex(random.gauss(0,1), random.gauss(0,1)) for n in range(M+1, M+N+1)}
lhs = 0.0
for q in range(1, Q+1):
    w = q / sum(1 for a in range(1, q+1) if math.gcd(a, q) == 1)
    for chi, prim in chars(q):
        if prim:
            lhs += w*abs(sum(c*ev(chi, q, n) for n, c in cs.items()))**2
rhs = (N + Q*Q)*sum(abs(c)**2 for c in cs.values())
