import cmath, math
from sympy import mobius, totient, primerange
def c(q, n):
    return sum(cmath.exp(2j*math.pi*n*r/q) for r in range(1, q+1) if math.gcd(r, q) == 1).real
def series(N, Q):
    return sum(int(mobius(q))*c(q, -N)/int(totient(q))**3 for q in range(1, Q+1))
def prod(N):
    s = 1.0
    for p in primerange(2, 10**5):
        s *= (1 - 1/(p-1)**2) if N % p == 0 else (1 + 1/(p-1)**3)
    return s
for N in (15, 16):
    assert abs(series(N, 400) - prod(N)) < 2e-3
assert prod(16) == 0.0

def need(k, M):
    pw = [i**k for i in range(1, M+1) if i**k <= M]
    INF = 10**9
    d = [0] + [INF]*M
    for n in range(1, M+1):
        b = INF
        for p in pw:
            if p > n: break
            if d[n-p] < b: b = d[n-p]
        d[n] = b + 1
    return d

